-- Phase 1.8: revenue funnel, vendor pursuit, message performance
create table if not exists public.vendor_registration_pursuits (id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,company_id uuid not null references public.companies(id) on delete cascade,status text not null default 'FOUND' check(status in ('FOUND','APPLIED','PENDING','QUALIFIED','EXPIRED')),portal_url text not null default '',applied_at timestamptz,qualified_at timestamptz,expires_at timestamptz,next_follow_up_at timestamptz,notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.vendor_registration_pursuits enable row level security; revoke all on public.vendor_registration_pursuits from anon; grant select,insert,update,delete on public.vendor_registration_pursuits to authenticated;
create policy vendor_registration_pursuits_owner_all on public.vendor_registration_pursuits for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
alter table public.messages add column if not exists trigger_type text not null default '', add column if not exists trigger_id uuid, add column if not exists persona text not null default '', add column if not exists commercial_objective text not null default '';
create table if not exists public.message_performance (id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,message_id uuid references public.messages(id) on delete cascade,company_id uuid references public.companies(id) on delete cascade,segment text not null default '',persona text not null default '',trigger_type text not null default '',sent integer not null default 0,delivered integer not null default 0,replies integer not null default 0,positive_replies integer not null default 0,referrals integer not null default 0,meetings integer not null default 0,vendor_registrations integer not null default 0,rfqs integer not null default 0,opportunities integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.message_performance enable row level security; revoke all on public.message_performance from anon; grant select,insert,update,delete on public.message_performance to authenticated;
create policy message_performance_owner_all on public.message_performance for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
